import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 채번 규칙 테이블 구조가 입력에 없어 번호 형식을 접두어-연도-ID 6자리로 정한다.
const CERT_NO_PREFIX = 'CERT';
const STATUSES = ['신청', '승인', '반려'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function parseId(value: string | undefined): string {
  if (value === undefined || !/^[0-9]{1,18}$/.test(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '증명서 ID 형식이 올바르지 않습니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr01603Controller {
  @Get('/certificates')
  async listCertificates(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const q = checks.queryOf(req.query);
    const rawPage = q['page'];
    const rawSize = q['size'];
    const page = rawPage === undefined || rawPage === '' ? 0 : Number(rawPage);
    let size = rawSize === undefined || rawSize === '' ? DEFAULT_SIZE : Number(rawSize);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const rawStatus = q['status'];
    const status = rawStatus === undefined || rawStatus === '' ? null : String(rawStatus);
    if (status !== null && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '상태 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const totalRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM certificate WHERE (CAST(:status AS varchar) IS NULL OR status = CAST(:status AS varchar))',
        { status },
      );
      const items = await db.query(
        'SELECT certificate_id AS "certificateId", certificate_form_id AS "certificateFormId", employee_id AS "employeeId", submission_to AS "submissionTo", copies AS "copies", status AS "status", certificate_no AS "certificateNo" '
          + 'FROM certificate WHERE (CAST(:status AS varchar) IS NULL OR status = CAST(:status AS varchar)) '
          + 'ORDER BY certificate_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { status, size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Post('/certificates/:certificateId/approve')
  @HttpCode(200)
  async approveCertificate(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const certificateId = parseId(req.params['certificateId']);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT c.status AS "status", f.numbering_rule_id AS "numberingRuleId" '
          + 'FROM certificate c JOIN certificate_form f ON f.certificate_form_id = c.certificate_form_id '
          + 'WHERE c.certificate_id = CAST(:certificateId AS bigint) FOR UPDATE OF c',
        { certificateId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CERTIFICATE_NOT_FOUND', '증명서 신청 건을 찾을 수 없습니다.');
      }
      if (found[0]['status'] !== '신청') {
        throw new ApiError(409, 'CERTIFICATE_STATUS_MISMATCH', '신청 상태가 아닌 건은 승인할 수 없습니다.');
      }
      if (found[0]['numberingRuleId'] === null || found[0]['numberingRuleId'] === undefined) {
        throw new ApiError(422, 'NUMBERING_RULE_NOT_CONFIGURED', '증명서 양식에 연결된 채번 규칙이 없습니다.');
      }
      const rows = await db.query(
        'UPDATE certificate SET status = \'승인\', '
          + 'certificate_no = :prefix || \'-\' || to_char(now(), \'YYYY\') || \'-\' || lpad(CAST(certificate_id AS text), 6, \'0\'), '
          + 'issued_date = CAST(now() AS date), updated_at = now() '
          + 'WHERE certificate_id = CAST(:certificateId AS bigint) AND status = \'신청\' '
          + 'RETURNING status AS "status", certificate_no AS "certificateNo"',
        { certificateId, prefix: CERT_NO_PREFIX },
      );
      if (rows.length === 0) {
        throw new ApiError(409, 'CERTIFICATE_STATUS_MISMATCH', '신청 상태가 아닌 건은 승인할 수 없습니다.');
      }
      return rows[0];
    });
  }

  @Post('/certificates/:certificateId/reject')
  @HttpCode(200)
  async rejectCertificate(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const certificateId = parseId(req.params['certificateId']);
    const data = checks.inputOf(req.body);
    const reason = typeof data['rejectReason'] === 'string' ? data['rejectReason'].trim() : '';
    if (reason === '') {
      throw new ApiError(422, 'REJECT_REASON_REQUIRED', '반려 사유를 입력해 주세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT status AS "status" FROM certificate WHERE certificate_id = CAST(:certificateId AS bigint) FOR UPDATE',
        { certificateId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CERTIFICATE_NOT_FOUND', '증명서 신청 건을 찾을 수 없습니다.');
      }
      if (found[0]['status'] !== '신청') {
        throw new ApiError(409, 'CERTIFICATE_STATUS_MISMATCH', '신청 상태가 아닌 건은 반려할 수 없습니다.');
      }
      const rows = await db.query(
        'UPDATE certificate SET status = \'반려\', reject_reason = :reason, updated_at = now() '
          + 'WHERE certificate_id = CAST(:certificateId AS bigint) AND status = \'신청\' '
          + 'RETURNING status AS "status"',
        { certificateId, reason },
      );
      if (rows.length === 0) {
        throw new ApiError(409, 'CERTIFICATE_STATUS_MISMATCH', '신청 상태가 아닌 건은 반려할 수 없습니다.');
      }
      return rows[0];
    });
  }
}

