import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Tiles,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  Select,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 10;

export default function FnSfr01603Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [applied, setApplied] = useState('');
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [mode, setMode] = useState<'view' | 'reject'>('view');
  const [reason, setReason] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/certificates', role, undefined, { status: applied, page, size: SIZE }),
    [applied, page, role],
  );
  const pending = useData<Page>(
    () => call<Page>('GET', '/certificates', role, undefined, { status: '신청', page: 0, size: 5 }),
    [role],
  );
  const approved = useData<Page>(
    () => call<Page>('GET', '/certificates', role, undefined, { status: '승인', page: 0, size: 1 }),
    [role],
  );
  const rejected = useData<Page>(
    () => call<Page>('GET', '/certificates', role, undefined, { status: '반려', page: 0, size: 1 }),
    [role],
  );

  function reloadAll() {
    list.reload();
    pending.reload();
    approved.reload();
    rejected.reload();
  }

  function open(row: Row) {
    setSelected(row);
    setMode('view');
    setReason('');
  }

  function close() {
    setSelected(null);
    setMode('view');
    setReason('');
  }

  async function approve() {
    if (!selected) return;
    await call('POST', '/certificates/' + String(selected['certificateId']) + '/approve', role, {});
    notify('증명서 신청을 승인했습니다.');
    close();
    reloadAll();
  }

  async function reject() {
    if (!selected) return;
    if (reason.trim() === '') {
      throw new Error('반려 사유를 입력해 주세요.');
    }
    await call('POST', '/certificates/' + String(selected['certificateId']) + '/reject', role, { rejectReason: reason });
    notify('증명서 신청을 반려했습니다.');
    close();
    reloadAll();
  }

  const columns = [
    { key: 'certificateId', label: '증명서 ID' },
    {
      key: 'certificateFormId',
      label: '증명서 양식',
      render: (r: Row) => <RefName table="certificate_form" role={role} value={r['certificateFormId']} />,
    },
    {
      key: 'employeeId',
      label: '신청자',
      render: (r: Row) => <RefName table="employee" role={role} value={r['employeeId']} />,
    },
    { key: 'submissionTo', label: '제출처' },
    { key: 'copies', label: '발급 부수' },
    { key: 'status', label: '상태', render: (r: Row) => <Badge value={r['status']} /> },
    { key: 'certificateNo', label: '증명서 번호' },
  ];

  const pendingColumns = [
    {
      key: 'employeeId',
      label: '신청자',
      render: (r: Row) => <RefName table="employee" role={role} value={r['employeeId']} />,
    },
    { key: 'submissionTo', label: '제출처' },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['처리 대기', pending.data ? pending.data.total : '-'],
            ['승인', approved.data ? approved.data.total : '-'],
            ['반려', rejected.data ? rejected.data.total : '-'],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>증명서 신청</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied(status);
          }}
          onReset={() => {
            setStatus('');
            setApplied('');
            setPage(0);
          }}
        >
          <Field label="상태">
            <Select
              value={status}
              onChange={setStatus}
              options={[['신청', '신청'], ['승인', '승인'], ['반려', '반려']]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={list.data ? list.data.total : undefined} />
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable columns={columns} rows={list.data ? list.data.items : []} onRowClick={open} empty="신청 건이 없습니다." />
        <Pager page={page} size={SIZE} total={list.data ? list.data.total : 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>처리 대기</h2>
        {pending.error ? <ErrorText text={pending.error} /> : null}
        <DataTable
          columns={pendingColumns}
          rows={pending.data ? pending.data.items : []}
          onRowClick={open}
          empty="대기 중인 신청이 없습니다."
        />
      </section>
      {selected ? (
        <Drawer title={mode === 'reject' ? '증명서 신청 반려' : '증명서 신청 검토'} onClose={close}>
          <Pairs
            items={[
              ['증명서 ID', String(selected['certificateId'])],
              ['증명서 양식', <RefName table="certificate_form" role={role} value={selected['certificateFormId']} />],
              ['신청자', <RefName table="employee" role={role} value={selected['employeeId']} />],
              ['제출처', String(selected['submissionTo'] ?? '')],
              ['발급 부수', String(selected['copies'] ?? '')],
              ['상태', <Badge value={selected['status']} />],
              ['증명서 번호', String(selected['certificateNo'] ?? '')],
            ]}
          />
          {selected['status'] === '신청' && mode === 'view' ? (
            <>
              <Form onSubmit={approve} submit="승인" note="승인하면 증명서 번호가 부여됩니다." />
              <button type="button" onClick={() => setMode('reject')}>반려</button>
            </>
          ) : null}
          {selected['status'] === '신청' && mode === 'reject' ? (
            <Form onSubmit={reject} submit="반려" danger>
              <Field label="반려 사유" required wide>
                <TextInput value={reason} onChange={setReason} multiline />
              </Field>
            </Form>
          ) : null}
        </Drawer>
      ) : null}
    </div>
  );
}
